  <script>
    // Product Carousel
    const track = document.getElementById('carousel-track');
    const btnLeft = document.querySelector('.carousel-btn-left');
    const btnRight = document.querySelector('.carousel-btn-right');
    const scrollAmount = 280;

    btnLeft.addEventListener('click', () => {
      track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });

    btnRight.addEventListener('click', () => {
      track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });

    // Store Locator Search
    const zipInput = document.getElementById('zip-input');
    const storeSearchBtn = document.getElementById('store-search-btn');
    const storeResults = document.getElementById('store-results');

    function searchStores() {
      const zip = zipInput.value.trim();
      if (zip.length === 5 && /^\d{5}$/.test(zip)) {
        storeResults.classList.add('active');
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }

    storeSearchBtn.addEventListener('click', searchStores);
    zipInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        searchStores();
      }
    });

    // Newsletter Signup
    const newsletterForm = document.getElementById('newsletter-form');
    const emailInput = document.getElementById('email-input');
    const confirmation = document.getElementById('newsletter-confirmation');

    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (emailInput.value.trim()) {
        newsletterForm.style.display = 'none';
        confirmation.classList.add('active');
      }
    });

    // Mobile menu toggle
    const mobileToggle = document.querySelector('.mobile-toggle');
    const navLinks = document.querySelector('.nav-links');

    mobileToggle.addEventListener('click', () => {
      const isOpen = navLinks.style.display === 'flex';
      navLinks.style.display = isOpen ? 'none' : 'flex';
      if (!isOpen) {
        navLinks.style.position = 'absolute';
        navLinks.style.top = '100%';
        navLinks.style.left = '0';
        navLinks.style.right = '0';
        navLinks.style.background = 'rgba(254,250,224,0.98)';
        navLinks.style.flexDirection = 'column';
        navLinks.style.padding = '20px 24px';
        navLinks.style.gap = '16px';
        navLinks.style.borderBottom = '1px solid rgba(45,106,79,0.1)';
      }
    });

    // Close mobile menu on link click
    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        if (window.innerWidth <= 768) {
          navLinks.style.display = 'none';
        }
      });
    });
  </script>

